118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        String address = normalizeAddress(ownerFieldsDto.getAddress());
120	        List<String> missingFields = new ArrayList<>();
121	        if (isBlank(ownerFieldsDto.getFirstName())) {
122	            missingFields.add("firstName");
123	        }
124	        if (isBlank(ownerFieldsDto.getLastName())) {
125	            missingFields.add("lastName");
126	        }
127	        if (isBlank(address)) {
128	            missingFields.add("address");
129	        }
130	        if (isBlank(ownerFieldsDto.getCity())) {
131	            missingFields.add("city");
132	        }
133	        if (isBlank(ownerFieldsDto.getTelephone())) {
134	            missingFields.add("telephone");
135	        }
136	        if (!missingFields.isEmpty()) {
137	            throw new MissingOwnerFieldsException(missingFields);
138	        }
139	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
140	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
141	        HttpHeaders headers = new HttpHeaders();
142	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
143	        owner.setAddress(address);
144	        owner.setTelephone(telephone);
145	        if (sharesHousehold) {
146	            owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
147	        }
148	        // All duplicate detection is consolidated into the single derived identity key: a create is
149	        // rejected only when the new owner's whole identity key equals an existing owner's.
150	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
151	            throw new DuplicateIdentityException(owner.getIdentityKey());
152	        }
153	        if (isCityAtCapacity(owner.getCity())) {
