167	        }
168	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
169	        this.clinicService.saveOwner(owner);
170	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
171	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
