274	    private static boolean isBlank(String value) {
275	        return value == null || value.isBlank();
276	    }
277	
278	    /**
279	     * Normalizes a street address into the canonical form stored on and returned for a newly
280	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
281	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
282	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
283	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
284	     * value is what gets persisted, echoed back, and used for every address comparison (household
285	     * duplicate detection and the shared household identifier).
286	     *
287	     * @param rawAddress the address value as supplied by the client
288	     * @return the normalized address (possibly empty, never {@code null})
289	     */
290	    private static String normalizeAddress(String rawAddress) {
291	        if (rawAddress == null) {
292	            return "";
293	        }
294	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
295	        if (collapsed.isEmpty()) {
296	            return "";
297	        }
298	        String[] tokens = collapsed.split(" ");
299	        StringBuilder sb = new StringBuilder(collapsed.length());
300	        for (int i = 0; i < tokens.length; i++) {
301	            String token = tokens[i];
302	            switch (token) {
303	                case "ST" -> token = "STREET";
304	                case "RD" -> token = "ROAD";
305	                case "AVE" -> token = "AVENUE";
306	                default -> { }
307	            }
308	            if (i > 0) {
309	                sb.append(' ');
310	            }
311	            sb.append(token);
312	        }
313	        return sb.toString();
314	    }
315	
316	    /**
317	     * Builds the customer code assigned to a newly created owner. The code is formatted
318	     * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three letters
319	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's
320	     * last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more
321	     * than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
322	     *
323	     * @param city the city of the owner being created
324	     * @param lastName the last name of the owner being created
325	     * @return the customer code to assign
326	     */
327	    private String nextCustomerCode(String city, String lastName) {
328	        String city3 = letterPrefix3(city);
329	        String last3 = letterPrefix3(lastName);
330	        String normalizedCity = normalizeIdentity(city);
331	        long sequence = this.clinicService.findAllOwners().stream()
332	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
333	            .count() + 1L;
334	        return String.format("%s-%s-%04d", city3, last3, sequence);
335	    }
336	
337	    /**
338	     * Returns the upper-cased first three letters of the given value, skipping any non-letter
339	     * characters. Values with fewer than three letters yield a shorter prefix.
340	     *
341	     * @param value the source text
342	     * @return the upper-cased letter prefix (at most three characters, never {@code null})
343	     */
344	    private static String letterPrefix3(String value) {
345	        StringBuilder prefix = new StringBuilder(3);
346	        if (value != null) {
347	            for (int i = 0; i < value.length() && prefix.length() < 3; i++) {
348	                char c = value.charAt(i);
349	                if (Character.isLetter(c)) {
350	                    prefix.append(Character.toUpperCase(c));
351	                }
352	            }
353	        }
354	        return prefix.toString();
355	    }
356	
357	    /**
358	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
359	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
360	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
361	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
362	     * the national number must match the country code: {@code +61} requires 9 national digits and
363	     * {@code +1} requires 10.
364	     *
365	     * @param rawTelephone the telephone value as supplied by the client
366	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
367	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
368	     */
369	    private static String normalizeTelephone(String rawTelephone) {
370	        if (rawTelephone == null) {
371	            throw new InvalidTelephoneException(rawTelephone);
372	        }
373	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
374	        String e164;
375	        if (cleaned.startsWith("+")) {
376	            String digits = cleaned.substring(1);
377	            if (!digits.matches("[0-9]+")) {
378	                throw new InvalidTelephoneException(rawTelephone);
379	            }
380	            e164 = "+" + digits;
381	        } else {
382	            if (!cleaned.matches("[0-9]+")) {
383	                throw new InvalidTelephoneException(rawTelephone);
384	            }
385	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
386	            e164 = "+61" + national;
387	        }
388	        int digitCount = e164.length() - 1;
389	        if (digitCount < 8 || digitCount > 15) {
390	            throw new InvalidTelephoneException(rawTelephone);
391	        }
392	        if (e164.startsWith("+61")) {
393	            if (e164.length() - "+61".length() != 9) {
394	                throw new InvalidTelephoneException(rawTelephone);
395	            }
396	        }
397	        else if (e164.startsWith("+1")) {
398	            if (e164.length() - "+1".length() != 10) {
399	                throw new InvalidTelephoneException(rawTelephone);
400	            }
401	        }
402	        return e164;
403	    }
404	
405	    /**
406	     * Determines whether any existing owner already carries the given identity key. The identity key
407	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
408	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
409	     * are equal.
410	     *
411	     * @param identityKey the identity key of the owner being created
412	     * @return {@code true} if another owner already has the same identity key
413	     */
414	    private boolean isIdentityKeyInUse(String identityKey) {
415	        return this.clinicService.findAllOwners().stream()
416	            .map(Owner::getIdentityKey)
417	            .anyMatch(identityKey::equals);
418	    }
419	
420	    /**
421	     * Counts how many existing owners already share the given first name and last name with the
422	     * owner being created. Both names are compared case-insensitively (after trimming and
423	     * collapsing runs of whitespace). The count reflects the state before the new owner is
424	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
425	     *
426	     * @param firstName the first name of the owner being created
427	     * @param lastName the last name of the owner being created
428	     * @return the number of existing owners sharing the same first and last name
429	     */
430	    private int namesakeCount(String firstName, String lastName) {
431	        String normalizedFirstName = normalizeIdentity(firstName);
432	        String normalizedLastName = normalizeIdentity(lastName);
433	        return (int) this.clinicService.findAllOwners().stream()
434	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
435	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
436	            .count();
437	    }
438	
439	    /**
440	     * Counts how many members the owner being created belongs to in its household, including
441	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
442	     * the new owner is not yet persisted, so its own membership is added to the existing count.
443	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
444	     * household of one.
445	     *
446	     * @param householdId the shared household identifier assigned to the owner being created, or
447	     *                    {@code null} if the owner does not share a household
448	     * @return the number of household members after this create (at least 1)
449	     */
450	    private int householdSizeAfterCreate(String householdId) {
451	        if (householdId == null) {
452	            return 1;
453	        }
454	        long existing = this.clinicService.findAllOwners().stream()
455	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
456	            .count();
457	        return (int) existing + 1;
458	    }
459	
460	    /**
461	     * The maximum number of owners permitted in a single city. Once a city already contains this
462	     * many owners it is considered full and no further owners may be created there.
463	     */
464	    private static final int CITY_CAPACITY = 50;
465	
466	    /**
467	     * Determines whether the given city has already reached its capacity, i.e. already contains
468	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
469	     * collapsing runs of whitespace to a single space and trimming.
470	     *
471	     * @param city the city of the owner being created
472	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
473	     */
474	    private boolean isCityAtCapacity(String city) {
475	        String normalizedCity = normalizeIdentity(city);
476	        long count = this.clinicService.findAllOwners().stream()
477	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
478	            .count();
479	        return count >= CITY_CAPACITY;
480	    }
481	
482	    /**
483	     * The maximum number of owners that may be created on any single day. Once this many owners
484	     * already carry a {@code registrationDate} of the current day, no further owners may be created
485	     * that day.
486	     */
487	    private static final int DAILY_REGISTRATION_LIMIT = 100;
488	
489	    /**
490	     * Determines whether the daily registration limit has already been reached, i.e. whether
491	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
492	     * their {@code registrationDate}.
493	     *
494	     * @param date the current day
495	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
496	     *         registered on the given date
497	     */
498	    /**
499	     * Rolls a registration date forward onto a business day. A date that already falls on a
500	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
501	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
502	     * everything derived from it (the membership number's year segment, the daily create-limit).
503	     *
504	     * @param date the effective registration date (supplied by the client or defaulted to the
505	     *             server's current date)
506	     * @return the same date if it is a weekday, otherwise the following Monday
507	     */
508	    private static LocalDate toBusinessDay(LocalDate date) {
509	        DayOfWeek dayOfWeek = date.getDayOfWeek();
510	        if (dayOfWeek == DayOfWeek.SATURDAY) {
511	            return date.plusDays(2);
512	        }
513	        if (dayOfWeek == DayOfWeek.SUNDAY) {
514	            return date.plusDays(1);
515	        }
516	        return date;
517	    }
518	
519	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
520	        long count = this.clinicService.findAllOwners().stream()
521	            .filter(existing -> date.equals(existing.getRegistrationDate()))
522	            .count();
523	        return count >= DAILY_REGISTRATION_LIMIT;
524	    }
525	
526	    /**
527	     * The number of owners that may be created on a single day before the bulk-signup warning is
528	     * raised. Once <em>more than</em> this many owners already carry the current business day as
529	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
530	     */
531	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
532	
533	    /**
534	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
535	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
536	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
537	     *
538	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
539	     *         registered on today's business day
540	     */
541	    private boolean isBulkSignupWarning() {
542	        LocalDate today = toBusinessDay(LocalDate.now());
543	        long count = this.clinicService.findAllOwners().stream()
544	            .filter(existing -> today.equals(existing.getRegistrationDate()))
545	            .count();
546	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
547	    }
548	
549	    /**
550	     * Back-fills the given household identifier onto every existing member of the household (those
551	     * sharing the same last name and address) that does not yet carry it, so all household members
552	     * share the stable identifier regardless of creation order. The identifier itself is derived
553	     * deterministically by {@link #householdIdFor(String, String)}.
554	     *
555	     * @param lastName the last name of the owner being created
556	     * @param address the address of the owner being created
557	     * @param householdId the stable household identifier assigned to the owner being created
558	     */
559	    private void backfillHousehold(String lastName, String address, String householdId) {
560	        String normalizedLastName = normalizeIdentity(lastName);
561	        String normalizedAddress = normalizeIdentity(address);
562	        for (Owner existing : this.clinicService.findAllOwners()) {
563	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
564	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
565	                && !householdId.equals(existing.getHouseholdId())) {
566	                existing.setHouseholdId(householdId);
567	                this.clinicService.saveOwner(existing);
568	            }
569	        }
570	    }
571	
572	    /**
573	     * Derives the stable household identifier for a given last name and address. The value is the
574	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
575	     * address, so it is stable across calls and identical for every member of the household.
576	     *
577	     * @param lastName the last name of the household
578	     * @param address the address of the household
579	     * @return the stable household identifier
580	     */
581	    private static String householdIdFor(String lastName, String address) {
582	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
583	        try {
584	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
585	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
586	            StringBuilder sb = new StringBuilder(digest.length * 2);
587	            for (byte b : digest) {
588	                sb.append(String.format("%02x", b));
589	            }
590	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
591	        }
592	        catch (java.security.NoSuchAlgorithmException e) {
593	            throw new IllegalStateException("SHA-256 not available", e);
594	        }
595	    }
596	
597	    /**
598	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
599	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
600	     * single space, and the result is lower-cased.
601	     *
602	     * @param value the raw field value
603	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
604	     */
605	    private static String normalizeIdentity(String value) {
606	        if (value == null) {
607	            return "";
608	        }
609	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
610	    }
611	}
